composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    depends_on:
      - {{serviceName}}-db
    environment:
      TZ: {{env.TZ}}
      LD_DB_HOST: {{serviceName}}-db
      LD_DB_PORT: {{env.LD_DB_PORT}}
      LD_DB_DATABASE: {{env.LD_DB_DATABASE}}
      LD_DB_USER: {{env.LD_DB_USER}}
      LD_DB_PASSWORD: {{env.LD_DB_PASSWORD}}
      LD_SECRET_KEY: {{env.LD_SECRET_KEY}}
    volumes:
      - {{appDataPath}}/data:/etc/linkding/data
  {{serviceName}}-db:
    image: mariadb:11
    container_name: {{containerName}}-db
    restart: unless-stopped
    environment:
      MARIADB_DATABASE: {{env.LD_DB_DATABASE}}
      MARIADB_USER: {{env.LD_DB_USER}}
      MARIADB_PASSWORD: {{env.LD_DB_PASSWORD}}
      MARIADB_RANDOM_ROOT_PASSWORD: "yes"
    volumes:
      - {{appDataPath}}/mysql:/var/lib/mysql
